naive_gemm_cpp = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

__global__ void naive_gemm_kernel(const float* A, const float* B, float* C, int M, int N, int Kdim) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if (row &lt; M &amp;&amp; col &lt; N) {
        float sum = 0.0f;
        for (int k = 0; k &lt; Kdim; ++k) {
            sum += A[row * Kdim + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor naive_matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int Kdim = A.size(1);
    int N = B.size(1);
    auto options = torch::TensorOptions().dtype(torch::kFloat).device(A.device());
    auto C = torch::zeros({(long)M, (long)N}, options);
    dim3 block(16, 16);
    dim3 grid((N + 15) / 16, (M + 15) / 16);
    naive_gemm_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(A.data_ptr&lt;float&gt;(), B.data_ptr&lt;float&gt;(), C.data_ptr&lt;float&gt;(), M, N, Kdim);
    return C;
}
"""

naive_matmul = load_inline(
    name="naive_matmul",
    cpp_sources=naive_gemm_cpp,
    functions=["naive_matmul_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.naive_matmul = naive_matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.naive_matmul.naive_matmul_hip(A, B)

def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, N)
    return [A, B]

def get_init_inputs():
    return []

