gemm_cpp = """
#include <hip/hip_runtime.h>

__global__ void gemm_simple(const float *A, const float *B, float *C, int M, int N, int K) {
    const int TS = 16;
    __shared__ float Ash[TS][TS];
    __shared__ float Bsh[TS][TS];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;
    int row = by * TS + ty;
    int col = bx * TS + tx;

    for (int kt = 0; kt < K; kt += TS) {
        // Load A tile
        if (row < M && kt + tx < K) {
            Ash[ty][tx] = A[row * K + kt + tx];
        } else {
            Ash[ty][tx] = 0.0f;
        }

        // Load B tile
        if (kt + ty < K && col < N) {
            Bsh[ty][tx] = B[(kt + ty) * N + col];
        } else {
            Bsh[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute products
#pragma unroll
        for (int kk = 0; kk < TS; ++kk) {
            sum += Ash[ty][kk] * Bsh[kk][tx];
        }

        __syncthreads();
    }

    // Write back
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor gemm_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto N = B.size(1);
    auto K = A.size(1);
    auto C = torch::zeros({M, N}, A.options());

    const int TS = 16;
    dim3 threads(TS, TS);
    dim3 blocks((N + TS - 1) / TS, (M + TS - 1) / TS);

    gemm_simple<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
"""

gemm = load_inline(
    name="gemm",
