bmm_cpp = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void simple_bmm_kernel(
    const float *A, 
    const float *B, 
    float *C,
    int bs, 
    int M, 
    int N, 
    int K
) {
    const int b = blockIdx.z;
    if (b >= bs) return;
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    const int j = blockIdx.y * blockDim.y + threadIdx.y;
    if (i >= M || j >= N) return;
    const size_t a_base = static_cast<size_t>(b) * M * K + static_cast<size_t>(i) * K;
    const size_t b_base = static_cast<size_t>(b) * K * N + static_cast<size_t>(j);
    const size_t c_idx = static_cast<size_t>(b) * M * N + static_cast<size_t>(i) * N + j;
    float sum = 0.0f;
    for (int l = 0; l < K; ++l) {
        sum += A[a_base + l] * B[b_base + l * N];
    }
    C[c_idx] = sum;
}

torch::Tensor simple_bmm_hip(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.device().is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.device().is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == at::ScalarType::Float, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::ScalarType::Float, "B must be float32");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3, "Expect 3D tensors");
    TORCH_CHECK(A.size(0) == B.size(0), "Batch sizes must match");
    TORCH_CHECK(A.size(2) == B.size(1), "Inner matrix dimensions must match (k)");

    int64_t bs = A.size(0);
    int64_t M = A.size(1);
    int64_t K = A.size(2);
    int64_t N = B.size(2);

    auto C = torch::zeros({bs, M, N}, A.options());

    dim3 threads(16, 16);
    dim3 blocks(
        (M + 15) / 16,
        (N + 15) / 16,
        static_cast<unsigned>(bs)
    );

    simple_bmm_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        static_cast<int>(bs),
        static_cast<int>(M),
        static_cast<int>(N),
        static_cast<int>(K)
    );

    return C;
}
"""

bmm_module = load_inline(
    name="simple_bmm",
    cpp_sources=bmm_cpp,
    functions=["simple_bmm_hip"],
    verbose=True
)

class ModelNew(nn.Module):
    """
    Custom batched matrix multiplication using simple HIP kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.bmm_module = bmm_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.bmm_module.simple_bmm_hip(A, B)

