#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

__global__ void rmsnorm_kernel(const float* __restrict__ x, float* __restrict__ out, float eps, int64_t N, int64_t F_, int64_t H, int64_t W, int64_t stride_f, int64_t hw_size) {
    uint32_t tid = threadIdx.x;
    uint32_t bid = blockIdx.x;
    int64_t pos = static_cast&lt;int64_t&gt;(bid);
    if (pos &gt;= N * hw_size) return;
    int64_t f = static_cast&lt;int64_t&gt;(tid);
    if (f &gt;= F_) return;
    int64_t n = pos / hw_size;
    int64_t g_hw = pos % hw_size;
    int64_t h = g_hw / W;
    int64_t w = g_hw % W;
    int64_t base = n * F_ * stride_f + h * W + w;
    constexpr int MAX_F = 256;
    __shared__ float sdata[MAX_F];
    __shared__ float rms_sh;
    // compute sum_sq
    int64_t idx = base + f * stride_f;
    float val = x[idx];
    sdata[tid] = val * val;
    __syncthreads();
    // parallel reduce
    int f_local = static_cast&lt;int&gt;(F_);
    for (int d = f_local / 2; d &gt; 0; d &gt;&gt;= 1) {
        if (static_cast&lt;int&gt;(tid) &lt; d) {
            sdata[tid] += sdata[tid + d];
        }
        __syncthreads();
    }
    if (tid == 0) {
        float mean_sq = sdata[0] / static_cast&lt;float&gt;(f_local);
        rms_sh = sqrtf(mean_sq + eps);
    }
    __syncthreads();
    // normalize
    val = x[idx];
    out[idx] = val / rms_sh;
}

torch::Tensor rmsnorm_hip(torch::Tensor x, float eps) {
    auto N_ = x.size(0);
    auto F_ = x.size(1);
    auto H_ = x.size(2);
    auto W_ = x.size(3);
    auto out = torch::empty_like(x);
    int64_t stride_f = H_ * W_;
    int64_t hw_size = stride_f;
    int64_t pos_size_ = N_ * hw_size;
    int block_size = static_cast&lt;int&gt;(F_);
    dim3 block(block_size);
    dim3 grid(static_cast&lt;unsigned int&gt;(pos_size_));
    hipLaunchKernelGGL(rmsnorm_kernel, grid, block, 0, 0, x.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), eps, N_, F_, H_, W_, stride_f, hw_size);
    return out;
}
"""

