conv2d_cpp_source = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

__global__ void conv2d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int Cin, int Cout, int Hin, int Win, int Hout, int Wout, int KH, int KW
) {
    unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_out = N * Cout * Hout * Wout;
    if (idx &gt;= total_out) return;

    int n = idx / (Cout * Hout * Wout);
    int temp = idx % (Cout * Hout * Wout);
    int oc = temp / (Hout * Wout);
    int temp2 = temp % (Hout * Wout);
    int oh = temp2 / Wout;
    int ow = temp2 % Wout;

    float sum = 0.0f;
    for (int c = 0; c &lt; Cin; c++) {
        for (int kh = 0; kh &lt; KH; kh++) {
            int ih = oh + kh;
            if (ih &gt;= Hin) continue;
            for (int kw = 0; kw &lt; KW; kw++) {
                int iw = ow + kw;
                if (iw &gt;= Win) continue;
                float i_val = input[((n * Cin + c) * Hin + ih) * Win + iw];
                float w_val = weight[((oc * Cin + c) * KH + kh) * KW + kw];
                sum += i_val * w_val;
            }
        }
    }
    output[((n * Cout + oc) * Hout + oh) * Wout + ow] = sum;
}

torch::Tensor conv2d_hip(torch::Tensor input, torch::Tensor weight) {
    auto batch = input.size(0);
    auto in_ch = input.size(1);
    auto in_h = input.size(2);
    auto in_w = input.size(3);
    auto out_ch = weight.size(0);
    auto w_in_ch = weight.size(1);
    auto k_h = weight.size(2);
    auto k_w = weight.size(3);

    if (w_in_ch != in_ch) {
        throw std::runtime_error("Groups != 1 not supported");
    }

    int out_h = in_h - k_h + 1;
    int out_w = in_w - k_w + 1;

    auto out_options = input.options();
    auto output = torch::zeros({batch, out_ch, out_h, out_w}, out_options);

    int n_elements = batch * out_ch * out_h * out_w;
    const int threads_per_block = 256;
    int blocks = (n_elements + threads_per_block - 1) / threads_per_block;

    hipStream_t stream = at::cuda::getCurrentHIPStream().stream();
    hipLaunchKernelGGL(
        conv2d_kernel,
        blocks,
        threads_per_block,
        0,
        stream,
        input.data_ptr&lt;float&gt;(),
        weight.data_ptr&lt;float&gt;(),
        output.data_ptr&lt;float&gt;(),
        batch, in_ch, out_ch, (int)in_h, (int)in_w, out_h, out_w, k_h, k_w
    );

    return output;
}
"""

