#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>  // not needed

static __inline__ __device__ float warpReduceSum(float val) {
  uint32_t mask = 0xffffffffu;
#pragma unroll
  for (int i = 32; i > 0; i >>= 1) {
    float temp = __shfl_xor_sync(mask, val, i);
    val += temp;
  }
  return val;
}

__global__ void gemv_kernel(const float* A, int lda, const float* B, float* C, int M, int K) {
  constexpr int warp_size = 64;
  int tid = threadIdx.x;
  int lane = tid % warp_size;
  int wid = tid / warp_size;
  int row = blockIdx.x * (blockDim.x / warp_size) + wid;
  if (row >= M) return;

  float sum = 0.0f;
  for (int col = lane; col < K; col += warp_size) {
    sum += A[row * lda + col] * B[col];
  }
  sum = warpReduceSum(sum);
  if (lane == 0) {
    C[row] = sum;
  }
}

torch::Tensor gemv_hip(torch::Tensor A, torch::Tensor B) {
  auto M = A.size(0);
  auto K = A.size(1);
  int lda = A.stride(0);

  auto options = A.options();
  torch::Tensor C = torch::zeros({(int64_t)M, 1}, options);

  auto A_ptr = A.data_ptr<float>();
  auto B_ptr = B.data_ptr<float>();
  auto C_ptr = C.data_ptr<float>();

  constexpr int warp_size = 64;
  constexpr int threads_per_block = 256;
  int warps_per_block = threads_per_block / warp_size;
  int num_blocks = (M + warps_per_block - 1) / warps_per_block;
  dim3 blocks(num_blocks);
  dim3 threads(threads_per_block);

  hipStream_t stream;
  hipStreamCreate(&stream);
  gemv_kernel<<<blocks, threads, 0, stream>>>(A_ptr, lda, B_ptr, C_ptr, (int)M, (int)K);
  hipStreamSynchronize(stream);
  hipStreamDestroy(stream);

  return C;
}
