    uint64_t total = (uint64_t)B * C * outH * outW;
    if ((uint64_t)tid >= total) return;

    unsigned int temp = tid;
    int ow = temp % outW;
    temp /= outW;
    int oh = temp % outH;
    temp /= outH;
    int c = temp % C;
    temp /= C;
    int b = temp % B;

    float acc = 0.0f;
    int ih0 = oh * stride - padding;
