    for (int kh = 0; kh < K; kh++) {
        int ih = ih0 + kh;
        if (ih < 0 || ih >= H) continue;
        for (int kw = 0; kw < K; kw++) {
            int iw = iw0 + kw;
            if (iw < 0 || iw >= W) continue;
            int input_offset = ((b * C + c) * H + ih) * W + iw;
            int weight_offset = c * K * K + kh * K + kw;
            acc += input[input_offset] * weight[weight_offset];
