__global__ void row_reduce_max(const float* input, float* output, int N) {
  extern __shared__ float sdata[];
  int tid = threadIdx.x;
  int row = blockIdx.x;
  float val = -3.402823466e+38F;
  for (int i = tid; i < N; i += blockDim.x) {
    val = fmaxf(val, input[row * N + i]);
  }
  sdata[tid] = val;
  __syncthreads();
  for (int s = blockDim.x / 2; s > 0; s >>= 1) {
    if (tid < s) {
      sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
    }
    __syncthreads();
  }
  if (tid == 0) {
    output[row] = sdata[0];
  }
}

__global__ void row_reduce_sum(const float* input, float* output, int N) {
  extern __shared__ float sdata[];
  int tid = threadIdx.x;
  int row = blockIdx.x;
  float val = 0.0f;
  for (int i = tid; i < N; i += blockDim.x) {
    val += input[row * N + i];
  }
  sdata[tid] = val;
  __syncthreads();
  for (int s = blockDim.x / 2; s > 0; s >>= 1) {
    if (tid < s) {
      sdata[tid] += sdata[tid + s];
    }
    __syncthreads();
  }
  if (tid == 0) {
    output[row] = sdata[0];
  }
}

__global__ void compute_exp_kernel(const float* x, const float* row_max, float* temp_exp, int B, int N) {
  size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
  if (idx >= (size_t)B * (size_t)N) return;
  int row = idx / N;
  temp_exp[idx] = expf(x[idx] - row_max[row]);
}

__global__ void normalize_kernel(const float* temp_exp, const float* row_sum, float* output, int B, int N) {
  size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
  if (idx >= (size_t)B * (size_t)N) return;
  int row = idx / N;
  output[idx] = temp_exp[idx] / row_sum[row];
}

