#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void conv2d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int Cin, int Cout, int Hin, int Win, int Hout, int Wout, int KH, int KW
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_out = N * Cout * Hout * Wout;
    if (idx >= total_out) return;

    int n = idx / (Cout * Hout * Wout);
    int temp = idx % (Cout * Hout * Wout);
    int oc = temp / (Hout * Wout);
    int temp2 = temp % (Hout * Wout);
    int oh = temp2 / Wout;
    int ow = temp2 % Wout;

    float sum = 0.0f;
    for (int c = 0; c < Cin; c++) {
        for (int kh = 0; kh < KH; kh++) {
            int ih = oh + kh;
            if (ih >= Hin) continue;
            for (int kw = 0; kw < KW; kw++) {
                int iw = ow + kw;
                if (iw >= Win) continue;
                float i_val = input[((n * Cin + c) * Hin + ih) * Win + iw];
                float w_val = weight[((oc * Cin + c) * KH + kh) * KW + kw];
                sum += i_val * w_val;
            }
        }
    }
    output[((n * Cout + oc) * Hout + oh) * Wout + ow] = sum;
}

torch::Tensor conv2d_hip(torch::Tensor input, torch::Tensor weight) {
    int N = input.size(0);
    int Cin = input.size(1);
    int Hin = input.size(2);
    int Win = input.size(3);
    int Cout = weight.size(0);
    int Cinw = weight.size(1);
    int KH = weight.size(2);
    int KW = weight.size(3);

    if (Cinw != Cin) {
        throw std::runtime_error("Groups != 1 not supported");
    }

    int Hout = Hin - KH + 1;
    int Wout = Win - KW + 1;

    auto output = torch::zeros({N, Cout, Hout, Wout}, input.options());

    int n_elements = N * Cout * Hout * Wout;
    const int threads_per_block = 256;
    int blocks = (n_elements + threads_per_block - 1) / threads_per_block;

    hipStream_t stream = 0;
    hipLaunchKernelGGL(conv2d_kernel, blocks, threads_per_block, 0, stream, input.data_ptr<float>(), weight.data_ptr<float>(), output.data_ptr<float>(), N, Cin, Cout, Hin, Win, Hout, Wout, KH, KW);

    return output;
}
