        __syncthreads();

        // Compute
        #pragma unroll
        for (int kk = 0; kk < TK; ++kk) {
            sum += Ash[ty][kk] * Bsh[kk][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
