#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define TILE_SIZE 16

__global__ void tiled_gemm_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    __shared__ float Ashare[TILE_SIZE][TILE_SIZE];
    __shared__ float Bshare[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int Row = blockIdx.y * TILE_SIZE + ty;
    int Col = blockIdx.x * TILE_SIZE + tx;

    float Pvalue = 0.0f;

    int num_tiles = (K + TILE_SIZE - 1) / TILE_SIZE;
    for (int m = 0; m < num_tiles; ++m) {
        // Load A tile
        if (Row < M && (m * TILE_SIZE + tx) < K) {
            Ashare[ty][tx] = A[Row * K + m * TILE_SIZE + tx];
        } else {
            Ashare[ty][tx] = 0.0f;
        }

        // Load B tile, note transposed access
        if (Col < N && (m * TILE_SIZE + ty) < K) {
            Bshare[ty][tx] = B[(m * TILE_SIZE + ty) * N + Col];
        } else {
            Bshare[ty][tx] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < TILE_SIZE; ++k) {
            Pvalue += Ashare[ty][k] * Bshare[k][tx];
        }

        __syncthreads();
    }

    if (Row < M && Col < N) {
        C[Row * N + Col] = Pvalue;
    }
}

