#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void rmsnorm_kernel(const float* __restrict__ x, float* __restrict__ out, float eps, int64_t N, int64_t F_, int64_t H, int64_t W, int64_t stride_f, int64_t hw_size) {
    uint32_t tid = threadIdx.x;
    uint32_t bid = blockIdx.x;
    int64_t pos = static_cast<int64_t>(bid);
    if (pos >= N * hw_size) return;
    int64_t f = static_cast<int64_t>(tid);
    if (f >= F_) return;
    int64_t n = pos / hw_size;
    int64_t g_hw = pos % hw_size;
    int64_t h = g_hw / W;
    int64_t w = g_hw % W;
    int64_t base = n * F_ * stride_f + h * W + w;
    constexpr int MAX_F = 256;
    __shared__ float sdata[MAX_F];
    __shared__ float rms_sh;
    // compute sum_sq
    int64_t idx = base + f * stride_f;
    float val = x[idx];
    sdata[tid] = val * val;
    __syncthreads();
    // parallel reduce
    int f_local = static_cast<int>(F_);
    for (int d = f_local / 2; d > 0; d >>= 1) {
        if (static_cast<int>(tid) < d) {
            sdata[tid] += sdata[tid + d];
        }
        __syncthreads();
    }
    if (tid == 0) {
        float mean_sq = sdata[0] / static_cast<float>(f_local);
        rms_sh = sqrtf(mean_sq + eps);
    }
    __syncthreads();
    // normalize
    val = x[idx];
    out[idx] = val / rms_sh;
}

