    auto N_ = x.size(0);
    auto F_ = x.size(1);
    auto H_ = x.size(2);
    auto W_ = x.size(3);
    auto out = torch::empty_like(x);
    int64_t stride_f = H_ * W_;
    int64_t hw_size = stride_f;
    int64_t pos_size_ = N_ * hw_size;
    int block_size = static_cast<int>(F_);
    dim3 block(block_size);
    dim3 grid(static_cast<unsigned int>(pos_size_));
    hipLaunchKernelGGL(rmsnorm_kernel, grid, block, 0, 0,
                       x.data_ptr<float>(), out.data_ptr<float>(), eps,
                       N_, F_, H_, W_, stride_f, hw_size);
    return out;
}
