    dim3 block(static_cast<unsigned int>(F_));
    dim3 grid(static_cast<unsigned int>(N_), static_cast<unsigned int>(H_), static_cast<unsigned int>(W_));
    hipLaunchKernelGGL(rmsnorm_kernel, grid, block, 0, 0,
