    auto options = A.options();
    auto C = torch::zeros({M, N}, options);

    const int TS = 32;
    dim3 block(TS, TS);
    dim3 grid((N + TS - 1) / TS, (M + TS - 1) / TS);
    size_t shmem = TS * TS * sizeof(float) * 2;

    tiled_matmul<<<grid, block, shmem>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
