__shared__ float b_smem[NUM_BUFFERS][BK][BLOCK_N];

__global__ void tiled_bmm_kernel(
    const float *A, 
    const float *B, 
    float *C,
    int bs, 
    int M, 
    int N, 
    int K
) {
    int b = blockIdx.z;
    if (b >= bs) return;

    const float *a = A + static_cast<size_t>(b) * M * K;
    const float *bb = B + static_cast<size_t>(b) * K * N;
    float *c = C + static_cast<size_t>(b) * M * N;

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float acc[WM][WN];
#pragma unroll
    for (int wm = 0; wm < WM; wm++) {
#pragma unroll
        for (int wn = 0; wn < WN; wn++) {
            acc[wm][wn] = 0.0f;
        }
    }

    int num_tiles_k = (K + BK - 1) / BK;

    // First tile
    {
        int kt = 0;
        int k_start = kt * BK;
        int load_idx = 0;
        int idx_a = ty * 16 + tx;
        while (idx_a < BLOCK_M * BK) {
            int row_a = idx_a / BK;
            int col_ka = idx_a % BK;
            int g_row_a = bx * BLOCK_M + row_a;
            if (g_row_a < M && k_start + col_ka < K) {
                a_smem[load_idx][row_a][col_ka] = a[g_row_a * K + k_start + col_ka];
            } else {
                a_smem[load_idx][row_a][col_ka] = 0.0f;
            }
            idx_a += 256;
        }
        int idx_b = ty * 16 + tx;
        while (idx_b < BK * BLOCK_N) {
            int row_kb = idx_b / BLOCK_N;
            int col_nb = idx_b % BLOCK_N;
            int g_col_b = by * BLOCK_N + col_nb;
            if (k_start + row_kb < K && g_col_b < N) {
                b_smem[load_idx][row_kb][col_nb] = bb[(k_start + row_kb) * N + g_col_b];
            } else {
                b_smem[load_idx][row_kb][col_nb] = 0.0f;
            }
            idx_b += 256;
        }
        __syncthreads();

        // Compute first tile
        int comp_idx = load_idx;
#pragma unroll
        for (int k_tile_local = 0; k_tile_local < BK; ++k_tile_local) {
#pragma unroll
            for (int wm = 0; wm < WM; ++wm) {
                float a_val = a_smem[comp_idx][(tx * WM) + wm][k_tile_local];
#pragma unroll
                for (int wn = 0; wn < WN; ++wn) {
                    float b_val = b_smem[comp_idx][k_tile_local][(ty * WN) + wn];
                    acc[wm][wn] += a_val * b_val;
                }
            }
        }
    }

    // Remaining tiles
    for (int kt = 1; kt < num_tiles_k; ++kt) {
        int k_start = kt * BK;
        int load_idx = kt % NUM_BUFFERS;
        int comp_idx = 1 - load_idx;

        // Load next tile
        int idx_a = ty * 16 + tx;
        while (idx_a < BLOCK_M * BK) {
            int row_a = idx_a / BK;
            int col_ka = idx_a % BK;
            int g_row_a = bx * BLOCK_M + row_a;
            if (g_row_a < M && k_start + col_ka < K) {
                a_smem[load_idx][row_a][col_ka] = a[g_row_a * K + k_start + col_ka];
            } else {
                a_smem[load_idx][row_a][col_ka] = 0.0f;
            }
            idx_a += 256;
        }
        int idx_b = ty * 16 + tx;
        while (idx_b < BK * BLOCK_N) {
            int row_kb = idx_b / BLOCK_N;
            int col_nb = idx_b % BLOCK_N;
            int g_col_b = by * BLOCK_N + col_nb;
            if (k_start + row_kb < K && g_col_b < N) {
                b_smem[load_idx][row_kb][col_nb] = bb[(k_start + row_kb) * N + g_col_b];
            } else {
                b_smem[load_idx][row_kb][col_nb] = 0.0f;
            }
            idx_b += 256;
        }
        __syncthreads();

        // Compute
#pragma unroll
        for (int k_tile_local = 0; k_tile_local < BK; ++k_tile_local) {
#pragma unroll
            for (int wm = 0; wm < WM; ++wm) {
                float a_val = a_smem[comp_idx][(tx * WM) + wm][k_tile_local];
#pragma unroll
                for (int wn = 0; wn < WN; ++wn) {
                    float b_val = b_smem[comp_idx][k_tile_local][(ty * WN) + wn];
                    acc[wm][wn] += a_val * b_val;
                }
            }
        }
    }

    // Write back C
    int row_start = bx * BLOCK_M + tx * WM;
    int col_start = by * BLOCK_N + ty * WN;
    if (row_start < M) {
#pragma unroll
        for (int wm = 0; wm < WM; ++wm) {
            int row = row_start + wm;
            if (row >= M) break;
#pragma unroll
            for (int wn = 0; wn < WN; ++wn) {
                int col = col_start + wn;
                if (col >= N) break;
                c[row * N + col] = acc[wm][wn];
            }
        }
    }
}

