#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <algorithm>

__global__ void gelu_kernel(const float *input, float *output, int64_t n) {
    size_t tid = blockIdx.x * (size_t)blockDim.x + threadIdx.x;
    for (size_t gid = tid; gid < (size_t)n; gid += blockDim.x * gridDim.x) {
        float x = input[gid];
        float x2 = x * x;
        float x3 = x2 * x;
        float d = 0.044715f * x3 + x;
        d *= 0.7978845608f;
        float t = tanhf(d);
        output[gid] = 0.5f * x * (1.0f + t);
    }
}

torch::Tensor custom_gelu_hip(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int64_t n = input.numel();
    const int block_size = 256;
    int full_blocks = (n + block_size - 1) / block_size;
    int num_blocks = std::min(65535, full_blocks);
    gelu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), n);
    return output;
}
