        // Load B tile
        if (Col < N && (m * TILE_SIZE + ty) < K) {
            Bshare[ty][tx] = B[(m * TILE_SIZE + ty) * N + Col];
        } else {
            Bshare[ty][tx] = 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            Pvalue += Ashare[ty][k] * Bshare[k][tx];
        }

        __syncthreads();
    }

    if (Row < M && Col < N) {
        C[Row * N + Col] = Pvalue;
    }
