#include <hip/hip_runtime.h>

__global__ void gemm_simple(const float *A, const float *B, float *C, int M, int N, int K) {
    const int TS_M = 32;
    const int TS_N = 16;
    const int TK = 128;
    const int BX = 16;
    const int BY = 32;
    __shared__ float Ash[TS_M][TK];
    __shared__ float Bsh[TK][TS_N];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;
    int row = by * TS_M + ty;
    int col = bx * TS_N + tx;

    const int phases_a = TK / BX;
    const int phases_b = TK / BY;

    for (int kt = 0; kt < K; kt += TK) {
        // Load A tile
#pragma unroll
        for (int phase = 0; phase < phases_a; ++phase) {
            int kidx = phase * BX + tx;
            int gk = kt + kidx;
            if (row < M && gk < K) {
                Ash[ty][kidx] = A[row * K + gk];
            } else {
                Ash[ty][kidx] = 0.0f;
            }
        }

        // Load B tile
#pragma unroll
        for (int phase = 0; phase < phases_b; ++phase) {
            int kidx = phase * BY + ty;
            int gk = kt + kidx;
            if (col < N && gk < K) {
                Bsh[kidx][tx] = B[gk * N + col];
            } else {
                Bsh[kidx][tx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute
#pragma unroll
        for (int kk = 0; kk < TK; ++kk) {
            sum += Ash[ty][kk] * Bsh[kk][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

