__global__ void conv2d_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int Cin, int Cout, int Hin, int Win, int Hout, int Wout, int KH, int KW
) {
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int bz = blockIdx.z;
    int n = bz / Cout;
    int oc = bz % Cout;
    int oh = by * 16 + ty;
    int ow = bx * 16 + tx;
    if (oh >= Hout || ow >= Wout || n >= N || oc >= Cout) return;

    float sum = 0.0f;
    #pragma unroll
    for (int c = 0; c < Cin; ++c) {
        #pragma unroll
        for (int kh = 0; kh < KH; ++kh) {
            int ih = oh + kh;
            if (ih >= Hin) continue;
            #pragma unroll
            for (int kw = 0; kw < KW; ++kw) {
                int iw = ow + kw;
                if (iw >= Win) continue;
                float i_val = input[((n * Cin + c) * Hin + ih) * Win + iw];
                float w_val = weight[((oc * Cin + c) * KH + kh) * KW + kw];
                sum += i_val * w_val;
            }
        }
    }
    output[((n * Cout + oc) * Hout + oh) * Wout + ow] = sum;
