__global__ void gemm_simple(const float *A, const float *B, float *C, int M, int N, int K) {
    const int TS = 32;
    const int TK = 128;
    __shared__ float Ash[TS][TK];
    __shared__ float Bsh[TK][TS];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;
    int row = by * TS + ty;
    int col = bx * TS + tx;

    const int n_phases = TK / TS;

    for (int kt = 0; kt < K; kt += TK) {
        // Load A tile - multiple phases
#pragma unroll
        for (int phase = 0; phase < n_phases; ++phase) {
            int kidx = phase * TS + tx;
            int gk = kt + kidx;
            if (row < M && gk < K) {
                Ash[ty][kidx] = A[row * K + gk];
            } else {
                Ash[ty][kidx] = 0.0f;
            }
        }

        // Load B tile - multiple phases
#pragma unroll
        for (int phase = 0; phase < n_phases; ++phase) {
            int kidx = phase * TS + ty;
            int gk = kt + kidx;
            if (col < N && gk < K) {
                Bsh[kidx][tx] = B[gk * N + col];
            } else {
                Bsh[kidx][tx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute
        for (int kk = 0; kk < TK; ++kk) {
            sum += Ash[ty][kk] * Bsh[kk][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

