        // Load B tile
        for(int j = 0; j < K_PER_THREAD; ++j) {
            int kk = m * K_TILE + ty + j * TILE_SIZE;
            if (Col < N && kk < K) {
                Bshare[ty + j * TILE_SIZE][tx] = B[kk * N + Col];
            } else {
                Bshare[ty + j * TILE_SIZE][tx] = 0.0f;
            }
